cat > /workspace/src/image.hpp << 'EOF'
#ifndef SCAMP_IMAGE_HPP
#define SCAMP_IMAGE_HPP

#include "core.h"
#include <array>
#include <bitset>
#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

struct ImageLoc { int stage = -1; uint32_t cell = 0; };
struct ImageFront { uint64_t key = 0; ImageLoc loc; };

// A detached, self-contained packed memory image.
struct ImageData {
    ImageLoc root;
    std::vector<ImageFront> front16, front64;
    std::array<uint32_t, RAM_NUM> cells{};
    std::array<std::vector<std::bitset<256> >, RAM_NUM> banks;
    std::vector<uint64_t> bitmaps;
    std::vector<uint32_t> nexthops;
};

// One validated node record.
struct ImageNode {
    int type;                 // 1..5
    int stage;
    uint32_t cell;
    int slot;                 // charged cells: 1 or 2
    uint32_t bmp;             // forwarding hop or BMP_NULL
    uint64_t bm;              // node-local NI bitmap pattern
    uint32_t nibase;          // base into the NI vector
    struct Kid {
        uint64_t key;
        int stage;
        uint32_t cell;
    };
    std::vector<Kid> kids;    // sorted by key
    struct Inl {
        ip6_t addr;
        int len;
        nexthop_t hop;
    };
    std::vector<Inl> inls;    // TYPE4: 1, TYPE5: 2
    int origin;               // 0, 16 or 64
    int depth;                // global node depth
};

// Validated lookup representation of a loaded image.  Depends only on the
// serialized image, never on live state or original prefix input.
struct ImageRep {
    std::vector<ImageNode> nodes;
    std::unordered_map<uint64_t, int> at;    // (stage<<22|cell) -> node index
    std::unordered_map<uint64_t, int> f16;   // front key -> node index
    std::unordered_map<uint64_t, int> f64;
    std::vector<nexthop_t> nexthops;
    int rootIdx;

    ImageRep() : rootIdx(-1) {}
};

class MemoryImage {
public:
    MemoryImage() = default;

    // Validate the complete self-contained image before replacing loaded
    // state.  On failure the previous complete image is preserved.
    bool load(const ImageData& proposed);

    // Longest prefix match over the loaded serialized image only.
    nexthop_t lookup(ip6_t ip) const;

private:
    ImageRep rep_;
};

std::string image_word_hex(const std::bitset<256>& bits);
std::bitset<256> image_word_from_hex(const std::string& text);

#endif
EOF
echo done
